import os
import secrets
import stat
from pathlib import Path


def generate_secrets() -> dict:
    return {
        "db_password": secrets.token_urlsafe(24),
        "redis_password": secrets.token_urlsafe(24),
        "secret_key": secrets.token_hex(32),
        # Encrypts backups only (#149), so SECRET_KEY can be rotated without
        # orphaning them.
        "backup_encryption_key": secrets.token_hex(32),
    }


def assemble_env(state: dict) -> str:
    db_pw = state["db_password"]
    redis_pw = state["redis_password"]
    lines = [
        "# IRDoc environment — generated by installer/wizard.py",
        "# Do not commit this file.",
        "",
        "# ─── Database ─────────────────────────────────────────────────────────────────",
        f"DB_PASSWORD={db_pw}",
        f"DATABASE_URL=postgresql+asyncpg://irp:{db_pw}@irdoc-db/irp",
        "",
        "# ─── Redis ──────────────────────────────────────────────────────────────────",
        f"REDIS_PASSWORD={redis_pw}",
        f"REDIS_URL=redis://:{redis_pw}@irdoc-redis:6379/0",
        "",
        "# ─── Security ───────────────────────────────────────────────────────────────",
        f"SECRET_KEY={state['secret_key']}",
        "# Encrypts backups. Keep a copy OFF this host: without it, backups can't be restored.",
        f"BACKUP_ENCRYPTION_KEY={state.get('backup_encryption_key') or secrets.token_hex(32)}",
        f"ACCESS_TOKEN_EXPIRE_MINUTES={state['access_token_expire_minutes']}",
        f"REFRESH_TOKEN_EXPIRE_DAYS={state['refresh_token_expire_days']}",
        "",
        "# ─── Application ────────────────────────────────────────────────────────────",
        f"BASE_URL={state['base_url']}",
        "ALLOW_REGISTRATION=false",
        f"LICENSE_KEY={state.get('license_key', '')}",
        f"VERSION={state.get('version', 'latest')}",
    ]
    legacy_keys = state.get("backup_legacy_secret_keys", "").strip()
    if legacy_keys:
        # Old SECRET_KEYs still needed to decrypt backups made before 0.1.10.
        at = next(i for i, line in enumerate(lines) if line.startswith("BACKUP_ENCRYPTION_KEY=")) + 1
        lines.insert(at, f"BACKUP_LEGACY_SECRET_KEYS={legacy_keys}")
    cors_origins = state.get("cors_origins", "").strip()
    if cors_origins:
        # Additional origins besides base_url — e.g. when analysts reach this
        # instance via localhost or a LAN IP during testing. The backend
        # already allows base_url plus localhost variants by default; this is
        # only needed for anything beyond that (custom domains, other hosts).
        lines.append(f"CORS_ORIGINS={state['base_url']},{cors_origins}")
    lines += [
        "",
        "# ─── Storage ────────────────────────────────────────────────────────────────",
        "STORAGE_BACKEND=local",
        "STORAGE_PATH=/app/storage",
        "",
        "# ─── Webhooks ───────────────────────────────────────────────────────────────",
        "WEBHOOK_RATE_LIMIT=20",
        "WEBHOOK_MAX_PAYLOAD_BYTES=65536",
    ]
    return "\n".join(lines) + "\n"


def read_existing_env(path: Path) -> dict:
    result = {}
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" in line:
            key, _, value = line.partition("=")
            result[key.strip()] = value.strip()
    return result


def write_env(path: Path, content: str) -> None:
    path.write_text(content, encoding="utf-8")
    os.chmod(path, stat.S_IRUSR | stat.S_IWUSR)  # 0o600
